#!/usr/bin/env node

/**
 * One-Stop Flight Search Script
 *
 * Uses the Amadeus Flight Offers Search API to find flights with exactly 1 stop.
 * Results are saved to /workspace/data/flight-results.json and flight-results.txt.
 *
 * Usage:
 *   node scripts/search-flights.mjs --origin JFK --destination LAX --date 2025-09-01 [options]
 *
 * Required:
 *   --origin        Departure airport IATA code (e.g. JFK)
 *   --destination   Arrival airport IATA code (e.g. LAX)
 *   --date          Departure date in YYYY-MM-DD format
 *
 * Optional:
 *   --return-date   Return date for round-trip (omit for one-way)
 *   --adults        Number of adult passengers (default: 1)
 *   --currency      Currency code (default: USD)
 *   --max-results   Maximum number of results to fetch (default: 50)
 *   --api-key       Amadeus API key (or set AMADEUS_API_KEY env var)
 *   --api-secret    Amadeus API secret (or set AMADEUS_API_SECRET env var)
 *
 * Sign up for free API credentials at: https://developers.amadeus.com
 */

import https from "node:https";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

// ---------------------------------------------------------------------------
// Config & CLI argument parsing
// ---------------------------------------------------------------------------

const DEFAULTS = {
  adults: 1,
  currency: "USD",
  maxResults: 50,
  apiKey: "YOUR_AMADEUS_API_KEY",
  apiSecret: "YOUR_AMADEUS_API_SECRET",
};

function printUsage() {
  console.log(`
Usage:
  node scripts/search-flights.mjs --origin <IATA> --destination <IATA> --date <YYYY-MM-DD> [options]

Required:
  --origin        Departure airport IATA code (e.g. JFK)
  --destination   Arrival airport IATA code (e.g. LAX)
  --date          Departure date (YYYY-MM-DD)

Optional:
  --return-date   Return date for round-trip (omit for one-way)
  --adults        Number of adult passengers (default: ${DEFAULTS.adults})
  --currency      Currency code (default: ${DEFAULTS.currency})
  --max-results   Max results to fetch (default: ${DEFAULTS.maxResults})
  --api-key       Amadeus API Key    (or env AMADEUS_API_KEY)
  --api-secret    Amadeus API Secret (or env AMADEUS_API_SECRET)
  --help          Show this help message
`);
}

function parseArgs(argv) {
  const args = {};
  for (let i = 2; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--help" || arg === "-h") {
      printUsage();
      process.exit(0);
    }
    if (arg.startsWith("--")) {
      const key = arg
        .slice(2)
        .replace(/-([a-z])/g, (_, c) => c.toUpperCase()); // kebab → camelCase
      const next = argv[i + 1];
      args[key] = next && !next.startsWith("--") ? argv[++i] : true;
    }
  }
  return args;
}

function resolveConfig(args) {
  const config = {
    origin: args.origin?.toUpperCase(),
    destination: args.destination?.toUpperCase(),
    date: args.date,
    returnDate: args.returnDate || null,
    adults: parseInt(args.adults, 10) || DEFAULTS.adults,
    currency: (args.currency || DEFAULTS.currency).toUpperCase(),
    maxResults: parseInt(args.maxResults, 10) || DEFAULTS.maxResults,
    apiKey: args.apiKey || process.env.AMADEUS_API_KEY || DEFAULTS.apiKey,
    apiSecret:
      args.apiSecret || process.env.AMADEUS_API_SECRET || DEFAULTS.apiSecret,
  };

  const missing = [];
  if (!config.origin) missing.push("--origin");
  if (!config.destination) missing.push("--destination");
  if (!config.date) missing.push("--date");
  if (missing.length) {
    console.error(`❌ Missing required arguments: ${missing.join(", ")}`);
    printUsage();
    process.exit(1);
  }

  if (!/^\d{4}-\d{2}-\d{2}$/.test(config.date)) {
    console.error(`❌ Invalid date format "${config.date}". Use YYYY-MM-DD.`);
    process.exit(1);
  }

  if (config.apiKey === DEFAULTS.apiKey || config.apiSecret === DEFAULTS.apiSecret) {
    console.error(
      "❌ Amadeus API credentials not set.\n" +
        "   Provide --api-key / --api-secret or set AMADEUS_API_KEY / AMADEUS_API_SECRET env vars.\n" +
        "   Sign up free at: https://developers.amadeus.com"
    );
    process.exit(1);
  }

  return config;
}

// ---------------------------------------------------------------------------
// HTTP helpers (built-in https — no dependencies)
// ---------------------------------------------------------------------------

function httpsRequest(url, options, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(url, options, (res) => {
      const chunks = [];
      res.on("data", (d) => chunks.push(d));
      res.on("end", () => {
        const raw = Buffer.concat(chunks).toString();
        try {
          resolve({ status: res.statusCode, data: JSON.parse(raw) });
        } catch {
          resolve({ status: res.statusCode, data: raw });
        }
      });
    });
    req.on("error", reject);
    if (body) req.write(body);
    req.end();
  });
}

// ---------------------------------------------------------------------------
// Amadeus API interaction
// ---------------------------------------------------------------------------

const AMADEUS_BASE = "test.api.amadeus.com"; // use "api.amadeus.com" for production

async function authenticate(apiKey, apiSecret) {
  console.log("🔑 Authenticating with Amadeus API…");

  const body = new URLSearchParams({
    grant_type: "client_credentials",
    client_id: apiKey,
    client_secret: apiSecret,
  }).toString();

  const { status, data } = await httpsRequest(
    `https://${AMADEUS_BASE}/v1/security/oauth2/token`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        "Content-Length": Buffer.byteLength(body),
      },
    },
    body
  );

  if (status !== 200 || !data.access_token) {
    console.error("❌ Authentication failed:", JSON.stringify(data, null, 2));
    process.exit(1);
  }

  console.log("✅ Authenticated successfully.");
  return data.access_token;
}

async function searchFlights(token, config) {
  console.log(
    `✈️  Searching one-stop flights: ${config.origin} → ${config.destination} on ${config.date}…`
  );

  const params = new URLSearchParams({
    originLocationCode: config.origin,
    destinationLocationCode: config.destination,
    departureDate: config.date,
    adults: String(config.adults),
    currencyCode: config.currency,
    max: String(config.maxResults),
    nonStop: "false", // we want connecting flights
  });

  if (config.returnDate) {
    params.set("returnDate", config.returnDate);
  }

  const url = `https://${AMADEUS_BASE}/v2/shopping/flight-offers?${params}`;

  const { status, data } = await httpsRequest(url, {
    method: "GET",
    headers: { Authorization: `Bearer ${token}` },
  });

  if (status !== 200) {
    console.error("❌ Search failed:", JSON.stringify(data, null, 2));
    process.exit(1);
  }

  return data;
}

// ---------------------------------------------------------------------------
// Result processing — filter & format
// ---------------------------------------------------------------------------

function filterOneStop(rawData) {
  const offers = rawData.data || [];
  const dictionaries = rawData.dictionaries || {};

  // Keep only offers where EVERY itinerary has exactly 2 segments (= 1 stop)
  const oneStop = offers.filter((offer) =>
    offer.itineraries.every((itin) => itin.segments.length === 2)
  );

  console.log(
    `📊 Found ${offers.length} total offers, ${oneStop.length} with exactly 1 stop.`
  );

  return { offers: oneStop, dictionaries };
}

function carrierName(code, dictionaries) {
  return dictionaries?.carriers?.[code] || code;
}

function formatDuration(isoDuration) {
  // PT2H35M → 2h 35m
  const match = isoDuration.match(/PT(?:(\d+)H)?(?:(\d+)M)?/);
  if (!match) return isoDuration;
  const h = match[1] ? `${match[1]}h` : "";
  const m = match[2] ? ` ${match[2]}m` : "";
  return (h + m).trim();
}

function computeLayover(seg1, seg2) {
  const arrive = new Date(seg1.arrival.at);
  const depart = new Date(seg2.departure.at);
  const diffMs = depart - arrive;
  const hours = Math.floor(diffMs / 3_600_000);
  const minutes = Math.floor((diffMs % 3_600_000) / 60_000);
  return `${hours}h ${minutes}m`;
}

function formatItinerary(itin, dictionaries, label) {
  const seg1 = itin.segments[0];
  const seg2 = itin.segments[1];

  const lines = [
    `  ${label}:`,
    `    Total duration : ${formatDuration(itin.duration)}`,
    `    Leg 1          : ${carrierName(seg1.carrierCode, dictionaries)} ${seg1.carrierCode}${seg1.number}`,
    `                     ${seg1.departure.iataCode} ${seg1.departure.at} → ${seg1.arrival.iataCode} ${seg1.arrival.at}`,
    `                     Duration: ${formatDuration(seg1.duration)}`,
    `    Layover        : ${seg1.arrival.iataCode} — ${computeLayover(seg1, seg2)}`,
    `    Leg 2          : ${carrierName(seg2.carrierCode, dictionaries)} ${seg2.carrierCode}${seg2.number}`,
    `                     ${seg2.departure.iataCode} ${seg2.departure.at} → ${seg2.arrival.iataCode} ${seg2.arrival.at}`,
    `                     Duration: ${formatDuration(seg2.duration)}`,
  ];
  return lines.join("\n");
}

function buildTextReport(offers, dictionaries, config) {
  const header = [
    "=".repeat(72),
    " ONE-STOP FLIGHT SEARCH RESULTS",
    "=".repeat(72),
    `  Route       : ${config.origin} → ${config.destination}`,
    `  Date        : ${config.date}${config.returnDate ? `  (return: ${config.returnDate})` : "  (one-way)"}`,
    `  Passengers  : ${config.adults} adult(s)`,
    `  Currency    : ${config.currency}`,
    `  Results     : ${offers.length} one-stop offer(s)`,
    "=".repeat(72),
    "",
  ];

  if (offers.length === 0) {
    header.push("No one-stop flights found for this route/date. Try different dates or airports.");
    return header.join("\n");
  }

  const blocks = offers.map((offer, idx) => {
    const lines = [`--- Offer ${idx + 1} --- Price: ${offer.price.total} ${offer.price.currency} ---`];

    offer.itineraries.forEach((itin, itinIdx) => {
      const label =
        offer.itineraries.length === 1
          ? "Outbound"
          : itinIdx === 0
            ? "Outbound"
            : "Return";
      lines.push(formatItinerary(itin, dictionaries, label));
    });

    // Booking class & seats remaining
    offer.travelerPricings?.[0]?.fareDetailsBySegment?.forEach((fd) => {
      lines.push(
        `    Cabin: ${fd.cabin || "N/A"}  Class: ${fd.class || "N/A"}  Seats left: ${fd.availabilityClasses?.[0]?.numberOfBookableSeats ?? "N/A"}`
      );
    });

    lines.push("");
    return lines.join("\n");
  });

  return header.join("\n") + blocks.join("\n");
}

// ---------------------------------------------------------------------------
// File output
// ---------------------------------------------------------------------------

function ensureDir(dirPath) {
  if (!fs.existsSync(dirPath)) fs.mkdirSync(dirPath, { recursive: true });
}

function saveResults(offers, dictionaries, config) {
  const outDir = path.resolve("/workspace/data");
  ensureDir(outDir);

  // JSON output
  const jsonPath = path.join(outDir, "flight-results.json");
  const jsonPayload = {
    searchParams: {
      origin: config.origin,
      destination: config.destination,
      date: config.date,
      returnDate: config.returnDate,
      adults: config.adults,
      currency: config.currency,
    },
    totalOneStopOffers: offers.length,
    generatedAt: new Date().toISOString(),
    offers,
    dictionaries,
  };
  fs.writeFileSync(jsonPath, JSON.stringify(jsonPayload, null, 2));
  console.log(`💾 JSON saved  → ${jsonPath}`);

  // Text report
  const txtPath = path.join(outDir, "flight-results.txt");
  const report = buildTextReport(offers, dictionaries, config);
  fs.writeFileSync(txtPath, report);
  console.log(`📄 Report saved → ${txtPath}`);
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  const args = parseArgs(process.argv);
  const config = resolveConfig(args);

  const token = await authenticate(config.apiKey, config.apiSecret);
  const rawData = await searchFlights(token, config);
  const { offers, dictionaries } = filterOneStop(rawData);

  saveResults(offers, dictionaries, config);

  // Print a brief summary to the console
  console.log("\n" + buildTextReport(offers, dictionaries, config));
  console.log("✅ Done!");
}

main().catch((err) => {
  console.error("❌ Unexpected error:", err);
  process.exit(1);
});
